def f(blocks: List[List[str]]):
    '''
    blocks: a list of blocks, where each block is a list of strings
    '''
    def evaluate_expression(expression):
        stack = []
        for token in expression.split():
            if token in "+-^":
                while stack and stack[-1] in "+-^":
                    stack.pop()
                stack.append(token)
            elif token == "(":
                stack.append(token)
            elif token == ")":
                while stack[-1]!= "(":
                    stack.pop()
                stack.pop()
            else:
                while stack and stack[-1] in "+-^":
                    stack.pop()
                stack.append(token)
        return stack

    def compare_expressions(expression1, expression2):
        stack1 = evaluate_expression(expression1)
        stack2 = evaluate_expression(expression2)
        return stack1 == stack2

    results = []
    for block in blocks:
        if len(block) == 1:
            results.append("YES")
        else:
            expressions = block[:-1]
            first_expression = " ".join(expressions[0].split())
            is_equal = all(compare_expressions(first_expression, " ".join(expression.split())) for expression in expressions[1:])
            results.append("YES" if is_equal else "NO")

    return "\n".join(results)
